// Episode calendar for the sidebar (and the mobile "Browse by date" card). Data: window.U51_EPISODES from assets/episodes.js,
// generated by build_site.py on every publish. Without JS the calendar stays hidden and the Archive list does the job.
(function () {
  var EPS = window.U51_EPISODES || [];
  if (!EPS.length) return;
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  var WD = [['M', 'Monday'], ['T', 'Tuesday'], ['W', 'Wednesday'], ['T', 'Thursday'], ['F', 'Friday'], ['S', 'Saturday'], ['S', 'Sunday']];
  var svg = function (d) { return '<svg class="icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="' + d + '"/></svg>'; };
  var byDay = {};
  EPS.forEach(function (e) { (byDay[e.d] = byDay[e.d] || []).push(e); });
  var mkey = function (y, m) { return y * 12 + m; };
  var first = EPS[0].d, last = EPS[EPS.length - 1].d;
  var minK = mkey(+first.slice(0, 4), +first.slice(5, 7) - 1), maxK = mkey(+last.slice(0, 4), +last.slice(5, 7) - 1);
  var today = '';
  try { today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Australia/Melbourne' }).format(new Date()); } catch (e) {}
  if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) { var n = new Date(); today = n.getFullYear() + '-' + ('0' + (n.getMonth() + 1)).slice(-2) + '-' + ('0' + n.getDate()).slice(-2); }
  var pad = function (v) { return ('0' + v).slice(-2); };
  var esc = function (s) { return String(s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };

  function render(root, k) {
    var y = Math.floor(k / 12), m = k % 12, current = root.getAttribute('data-current') || '', base = root.getAttribute('data-root') || '';
    var startDow = (new Date(y, m, 1).getDay() + 6) % 7, days = new Date(y, m + 1, 0).getDate();
    var h = '<div class="cal-head"><button type="button" class="cal-nav" data-step="-1" aria-label="Previous month"' + (k <= minK ? ' disabled' : '') + '>' + svg('m15 18-6-6 6-6') + '</button>' +
      '<p class="cal-title" aria-live="polite">' + MONTHS[m] + ' ' + y + '</p>' +
      '<button type="button" class="cal-nav" data-step="1" aria-label="Next month"' + (k >= maxK ? ' disabled' : '') + '>' + svg('m9 18 6-6-6-6') + '</button></div>' +
      '<table class="cal-grid"><caption class="sr-only">Episodes in ' + MONTHS[m] + ' ' + y + '</caption><thead><tr>' +
      WD.map(function (w) { return '<th scope="col" abbr="' + w[1] + '">' + w[0] + '</th>'; }).join('') + '</tr></thead><tbody><tr>';
    for (var i = 0; i < startDow; i++) h += '<td></td>';
    for (var d = 1; d <= days; d++) {
      var iso = y + '-' + pad(m + 1) + '-' + pad(d), list = byDay[iso], cls = 'cal-day' + (iso === today ? ' is-today' : '') + (iso === current ? ' is-current' : '');
      var nice = d + ' ' + MONTHS[m] + ' ' + y;
      if (list) {
        var more = list.length > 1 ? ', and ' + (list.length - 1) + ' more' : '';
        var tip = list.map(function (e) { return e.t; }).join('\n');
        h += '<td><a class="' + cls + ' has-ep" href="' + esc(base + list[0].u) + '" title="' + esc(tip) + '" aria-label="' + esc(list[0].n + more + ', ' + nice) + '"' +
          (iso === current ? ' aria-current="date"' : '') + '>' + d + (list.length > 1 ? '<span class="cal-count" aria-hidden="true">' + list.length + '</span>' : '') + '</a></td>';
      } else {
        h += '<td><span class="' + cls + '" aria-label="' + nice + ', no episode">' + d + '</span></td>';
      }
      if ((startDow + d) % 7 === 0 && d < days) h += '</tr><tr>';
    }
    var tail = (7 - (startDow + days) % 7) % 7;
    for (i = 0; i < tail; i++) h += '<td></td>';
    root.innerHTML = h + '</tr></tbody></table>';
    root._k = k;
  }

  document.querySelectorAll('[data-cal]').forEach(function (root) {
    var cur = root.getAttribute('data-current') || '', ref = cur || today;
    var k = mkey(+ref.slice(0, 4), +ref.slice(5, 7) - 1);
    if (k < minK || k > maxK) k = maxK;   // open on the current (or viewed) month, else the latest month with episodes
    render(root, k);
    root.addEventListener('click', function (ev) {
      var b = ev.target.closest('.cal-nav');
      if (!b || b.disabled) return;
      var step = +b.getAttribute('data-step'), nk = Math.min(maxK, Math.max(minK, root._k + step));
      render(root, nk);
      var again = root.querySelector('.cal-nav[data-step="' + step + '"]');
      (again && !again.disabled ? again : root.querySelector('.cal-nav:not([disabled])') || root).focus();
    });
  });
})();
